(()=>{'use strict';const section=document.querySelector('#rouha'),dialog=document.querySelector('#rhLightbox');if(!section||!dialog)return;const buttons=[...section.querySelectorAll('[data-rh-photo]')].sort((a,b)=>Number(a.dataset.rhPhoto)-Number(b.dataset.rhPhoto)),full=document.querySelector('#rhFullImage'),counter=document.querySelector('#rhCounter');let index=0,lastButton=null;const t=s=>window.I18N?.t(s)||s;const more=document.querySelector('#rhShowAll');more.addEventListener('click',()=>{const expanded=more.getAttribute('aria-expanded')!=='true';more.setAttribute('aria-expanded',String(expanded));section.classList.toggle('rh-expanded',expanded);more.textContent=t(expanded?'عرض صور أقل':'عرض كل الصور (١٨)')});function show(i){index=(i+buttons.length)%buttons.length;const image=buttons[index].querySelector('img');full.src=image.getAttribute('src');full.alt=image.alt;counter.textContent=(index+1)+' / '+buttons.length}function close(){dialog.close();lastButton?.focus()}section.addEventListener('click',e=>{const button=e.target.closest('[data-rh-photo]');if(!button)return;lastButton=button;show(Number(button.dataset.rhPhoto));if(typeof dialog.showModal==='function')dialog.showModal();else window.open(full.src,'_blank','noopener')});document.querySelector('#rhClose').addEventListener('click',close);document.querySelector('#rhPrevious').addEventListener('click',()=>show(index-1));document.querySelector('#rhNext').addEventListener('click',()=>show(index+1));dialog.addEventListener('click',e=>{if(e.target===dialog)close()});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();show(index+1)}if(e.key==='ArrowLeft'){e.preventDefault();show(index-1)}});dialog.addEventListener('close',()=>lastButton?.focus());function labels(){buttons.forEach((b,i)=>{b.setAttribute('aria-label',t('عرض الصورة')+' '+(i+1));b.querySelector('img').alt=t('الروحة')+' · '+(i+1)});more.textContent=t(more.getAttribute('aria-expanded')==='true'?'عرض صور أقل':'عرض كل الصور (١٨)');dialog.setAttribute('aria-label',t('الروحة'));document.querySelector('#rhClose').setAttribute('aria-label',t('إغلاق'));document.querySelector('#rhPrevious').setAttribute('aria-label',t('الصورة السابقة'));document.querySelector('#rhNext').setAttribute('aria-label',t('الصورة التالية'))}labels();window.addEventListener('languagechange',labels);const video=section.querySelector('video');video.addEventListener('play',()=>{document.querySelectorAll('video').forEach(v=>{if(v!==video&&!v.paused)v.pause()})});})();
